const results = [];

for (const item of $input.all()) {
  let rawText = item.json.text || item.json.output || item.json.message || "";

  rawText = rawText.trim();
  if (rawText.startsWith("```")) {
    rawText = rawText.replace(/^```(?:json)?/i, "").replace(/```$/, "").trim();
  }

  try {
    const parsedData = JSON.parse(rawText);

    let isQuantityMatch = true;
    const itemTracker = {}; // Dictionary to group quantities by product

    // 1. Process matched items to aggregate deliveries per invoice line
    if (parsedData.matched_delivery_notes && Array.isArray(parsedData.matched_delivery_notes)) {
      for (const dn of parsedData.matched_delivery_notes) {
        if (dn.matched_items && Array.isArray(dn.matched_items)) {
          for (const mItem of dn.matched_items) {
            // Use article number if available, otherwise description as unique key
            const key = mItem.invoice_article_number || mItem.invoice_item || "UNKNOWN_ITEM";

            // Initialize the item in our tracker if it doesn't exist yet
            if (!itemTracker[key]) {
              itemTracker[key] = {
                invoiced: Number(mItem.invoiced_quantity) || 0,
                delivered: 0
              };
            }
            // Add this specific delivery to the running total for this item
            itemTracker[key].delivered += (Number(mItem.delivered_quantity) || 0);
          }
        }
      }
    }

    // 2. Add unmatched items so they are accounted for (delivered = 0)
    if (parsedData.unmatched_invoice_items && Array.isArray(parsedData.unmatched_invoice_items)) {
      for (const uItem of parsedData.unmatched_invoice_items) {
        const key = uItem.article_number || uItem.invoice_item || "UNKNOWN_ITEM";
        if (!itemTracker[key]) {
          itemTracker[key] = {
            invoiced: Number(uItem.quantity) || 0,
            delivered: 0
          };
        }
      }
    }

    // 3. Evaluate totals per item strictly
    const discrepancy_details = [];
    const tracking_keys = Object.keys(itemTracker);

    if (tracking_keys.length === 0) {
        isQuantityMatch = false; 
        discrepancy_details.push("No line items found to evaluate.");
    } else {
        for (const key of tracking_keys) {
          const totals = itemTracker[key];
          if (totals.invoiced !== totals.delivered) {
            isQuantityMatch = false;
            discrepancy_details.push(`Mismatch on '${key}': Billed ${totals.invoiced}, Delivered ${totals.delivered}`);
          }
        }
    }

    // 4. Final routing logic: Must be a semantic "matched" AND mathematically perfect
    const finalAction = (parsedData.result === "matched" && isQuantityMatch) ? "APPROVE" : "REVIEW_EXCEPTION";

    results.push({
      json: {
        ...parsedData, 
        _routing: {
          is_quantity_match: isQuantityMatch,
          discrepancy_details: discrepancy_details,
          item_totals: itemTracker,
          action: finalAction
        }
      }
    });

  } catch (error) {
    results.push({
      json: {
        invoice_id: "PARSE_ERROR",
        result: "error",
        notes: "Failed to parse AI JSON output.",
        raw_ai_text: rawText,
        _routing: {
          is_quantity_match: false,
          discrepancy_details: ["Critical JSON Parse Error from AI"],
          action: "REVIEW_EXCEPTION"
        }
      }
    });
  }
}

return results;

// ============================================================
// GET ALREADY-FILTERED DATA FROM GOOGLE SHEETS
// ============================================================

const invoices = $('get candidate invoices').all().map(item => item.json);
const deliveryNotes = $('Get candidate DNs').all().map(item => item.json);


// ============================================================
// DATE PARSING
// Supports: YYYY-MM-DD, DD/MM/YYYY, DD-MM-YYYY
// ============================================================

function parseDate(dateStr) {
    if (!dateStr) return null;

    const value = String(dateStr).trim();

    let day, month, year;
    let match;

    // YYYY-MM-DD
    match = value.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);

    if (match) {
        year = Number(match[1]);
        month = Number(match[2]);
        day = Number(match[3]);
    } else {
        // DD/MM/YYYY or DD-MM-YYYY
        match = value.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/);

        if (match) {
            day = Number(match[1]);
            month = Number(match[2]);
            year = Number(match[3]);
        }
    }

    if (!day || !month || !year) return null;

    const date = new Date(Date.UTC(year, month - 1, day));

    // Reject impossible dates
    if (
        date.getUTCFullYear() !== year ||
        date.getUTCMonth() !== month - 1 ||
        date.getUTCDate() !== day
    ) {
        return null;
    }

    return date.getTime();
}


// ============================================================
// TEXT NORMALIZATION
// ============================================================

function normalizeText(value) {
    return String(value || "")
        .toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/[^a-z0-9]+/g, " ")
        .trim()
        .replace(/\s+/g, " ");
}


// ============================================================
// LEVENSHTEIN SIMILARITY
// Returns 0 → completely different, 1 → identical
// ============================================================

function similarity(a, b) {
    a = normalizeText(a);
    b = normalizeText(b);

    if (!a || !b) return 0;
    if (a === b) return 1;

    const matrix = Array.from(
        { length: a.length + 1 },
        () => new Array(b.length + 1).fill(0)
    );

    for (let i = 0; i <= a.length; i++) matrix[i][0] = i;
    for (let j = 0; j <= b.length; j++) matrix[0][j] = j;

    for (let i = 1; i <= a.length; i++) {
        for (let j = 1; j <= b.length; j++) {
            const cost = a[i - 1] === b[j - 1] ? 0 : 1;
            matrix[i][j] = Math.min(
                matrix[i - 1][j] + 1,
                matrix[i][j - 1] + 1,
                matrix[i - 1][j - 1] + cost
            );
        }
    }

    const distance = matrix[a.length][b.length];
    const maxLength = Math.max(a.length, b.length);

    return 1 - (distance / maxLength);
}


// ============================================================
// SUPPLIER SIMILARITY
// ============================================================

function supplierSimilarity(supplierA, supplierB) {
    const a = normalizeText(supplierA);
    const b = normalizeText(supplierB);

    if (!a || !b) return 0;
    if (a === b) return 1;

    const fullSimilarity = similarity(a, b);

    // Remove common legal/business words
    const ignoredWords = new Set([
        "bv", "nv", "sa", "sarl", "sprl", "ltd", "llc", 
        "inc", "corp", "company", "co", "group", "groupe"
    ]);

    const wordsA = a.split(" ").filter(word => word && !ignoredWords.has(word));
    const wordsB = b.split(" ").filter(word => word && !ignoredWords.has(word));

    if (wordsA.length === 0 || wordsB.length === 0) return fullSimilarity;

    let matchedTokens = 0;

    for (const wordA of wordsA) {
        let bestMatch = 0;
        for (const wordB of wordsB) {
            const score = similarity(wordA, wordB);
            if (score > bestMatch) bestMatch = score;
        }
        if (bestMatch >= 0.80) matchedTokens++;
    }

    const tokenSimilarity = matchedTokens / Math.max(wordsA.length, wordsB.length);

    return (0.75 * fullSimilarity) + (0.25 * tokenSimilarity);
}

// ============================================================
// LINE ITEM EXTRACTION HELPER
// ============================================================

function extractLineItems(item) {
    if (!item) return [];

    if (item.JSON) {
        try {
            const parsed = typeof item.JSON === 'string' ? JSON.parse(item.JSON) : item.JSON;
            if (parsed.InvoiceLine) return parsed.InvoiceLine;
            if (parsed.line_items) return parsed.line_items;
            return parsed;
        } catch (e) {
            return ["Error parsing JSON string from sheet"];
        }
    }

    if (item.line_items) return item.line_items;
    if (item.Raw_Items) {
        try { return JSON.parse(item.Raw_Items); } catch(e) { return item.Raw_Items; }
    }

    return ["No line items passed in payload"];
}


// ============================================================
// SETTINGS
// ============================================================

const SUPPLIER_THRESHOLD = 0.70;


// ============================================================
// PROCESS EACH INVOICE
// ============================================================

const results = [];

for (const invoice of invoices) {

    const invDateStr = invoice.Issue_Date || invoice.Date;
    const invoiceDate = parseDate(invDateStr);

    // --------------------------------------------------------
    // Invalid invoice date
    // --------------------------------------------------------

    if (invoiceDate === null) {
        results.push({
            json: {
                matching_data: {
                    type: "invalid_invoice",
                    invoice: {
                        id: invoice.Invoice_ID || invoice["Document ID"] || null,
                        supplier: invoice.Supplier_Name || invoice.Supplier || null,
                        date: invDateStr,
                        line_items: extractLineItems(invoice),
                        metadata: invoice
                    },
                    error: "Invalid or missing invoice date",
                    candidate_count: 0,
                    candidate_delivery_notes: [],
                    invalid_date_delivery_notes: []
                }
            }
        });
        continue;
    }


    const candidateDNs = [];
    const invalidDateDNs = [];

    // --------------------------------------------------------
    // Compare this invoice against every available DN
    // --------------------------------------------------------

    for (const dn of deliveryNotes) {

        const dnDateStr = dn.Delivery_date || dn.Date;
        const dnDate = parseDate(dnDateStr);

        // --- ID FALLBACK BUG FIX ---
        // Pre-calculating the correct ID string to prevent 'null' dropping in JSON
        const dnId = dn.Delivery_note_reference || dn.delivery_note_reference || dn.DN_Number || dn.Document_ID || dn.id || null;

        // ----------------------------------------------------
        // Invalid DN date
        // ----------------------------------------------------

        if (dnDate === null) {
            invalidDateDNs.push({
                id: dnId,
                metadata: dn
            });
            continue;
        }

        // ----------------------------------------------------
        // Chronological filter
        // ----------------------------------------------------

        if (dnDate > invoiceDate) continue;

        // ----------------------------------------------------
        // Supplier similarity
        // ----------------------------------------------------

        const invSupplierStr = invoice.Supplier_Name || invoice.Supplier;
        const dnSupplierStr = dn.Supplier_name || dn.Supplier;

        const supplierScore = supplierSimilarity(invSupplierStr, dnSupplierStr);

        if (supplierScore < SUPPLIER_THRESHOLD) continue;

        // ----------------------------------------------------
        // Candidate Assembly
        // ----------------------------------------------------

        candidateDNs.push({
            id: dnId,
            supplier: dnSupplierStr || null,
            date: dnDateStr || null,
            supplier_similarity: Number(supplierScore.toFixed(3)),
            line_items: extractLineItems(dn), 
            metadata: dn
        });
    }

    // --------------------------------------------------------
    // Highest supplier similarity first
    // --------------------------------------------------------

    candidateDNs.sort((a, b) => b.supplier_similarity - a.supplier_similarity);

    // ========================================================
    // FINAL DATA OBJECT
    // ========================================================

    results.push({
        json: {
            matching_data: {
                type: "invoice_candidates",
                candidate_count: candidateDNs.length,
                invoice: {
                    id: invoice.Invoice_ID || invoice["Document ID"] || null,
                    supplier: invoice.Supplier_Name || invoice.Supplier || null,
                    date: invDateStr,
                    line_items: extractLineItems(invoice), 
                    metadata: invoice
                },
                candidate_delivery_notes: candidateDNs,
                invalid_date_delivery_notes: invalidDateDNs
            }
        }
    });
}

// ============================================================
// OUTPUT
// ============================================================

return results;
